import type { ColumnDescriptor, ColumnType, TableDescriptor } from "@rebasepro/types";
import { isNumericColumnType } from "@rebasepro/types";

import type { PrimaryKeyInfo } from "../util/identity";
import { isDateOnlyType, isSerialType } from "./column-types";

/**
 * How the value of a key column comes to be.
 *
 * - `uuid` — a `uuid` column (generated by `gen_random_uuid()` or given);
 * - `serial` — a `smallserial` / `serial` / `bigserial`;
 * - `identity` — an integer column `GENERATED BY DEFAULT AS IDENTITY`;
 * - `integer` — any other `smallint` / `integer` / `bigint`: the caller gives it;
 * - `text` — `text`, `varchar` or `char`;
 * - `other` — any other type (a day, a numeric, an enum, …).
 *
 * @group Table
 */
export type KeyIdentity = "uuid" | "serial" | "identity" | "integer" | "text" | "other";

/**
 * One column of a table's primary key.
 *
 * @group Table
 */
export interface TableKeyColumn {
    /** The column key: what a row and an address name. */
    key: string;
    /** The SQL column name. */
    column: string;
    /** The column's Postgres type. */
    type: ColumnType;
    /** How its value comes to be. */
    identity: KeyIdentity;
    /** Whether the database fills it when an insert leaves it out. */
    generated: boolean;
}

/**
 * The primary-key columns of a table, in key order.
 *
 * Read from `descriptor.primaryKey` and the column types — one answer. It
 * replaces the driver's three-tier `getPrimaryKeys` (`isId` properties, then
 * the drizzle table's primary key, then a column literally named `id`) and the
 * `isId` reads beside it (`"uuid"`, `"increment"`, `true`): a compiled table
 * always states its key, so there is nothing to infer.
 *
 * Empty only for a table introspected from a database whose table has no
 * primary key; a declared table without one does not compile.
 *
 * @group Table
 */
export function keyColumns(table: TableDescriptor): TableKeyColumn[] {
    const out: TableKeyColumn[] = [];
    for (const key of table.primaryKey) {
        const column = table.columns.find(candidate => candidate.key === key);
        if (!column) continue;
        out.push(keyColumnOf(column));
    }
    return out;
}

/**
 * One column as a key column: its identity and whether the database fills it.
 *
 * @group Table
 */
export function keyColumnOf(column: ColumnDescriptor): TableKeyColumn {
    return {
        key: column.key,
        column: column.column,
        type: column.type,
        identity: identityOf(column),
        generated: isGeneratedKey(column)
    };
}

/**
 * The key columns as the address helpers read them (`buildCompositeId`,
 * `parseIdValues`, `isAddressableId` — the shape `getPrimaryKeys` returned):
 * `number` for a numeric column, `isUUID` for a `uuid` one, `isDay` for a
 * `date` one.
 *
 * @group Table
 */
export function keyAddressInfo(table: TableDescriptor): PrimaryKeyInfo[] {
    return keyColumns(table).map(keyAddressInfoOf);
}

/**
 * One key column as the address helpers read it.
 *
 * @group Table
 */
export function keyAddressInfoOf(column: Pick<TableKeyColumn, "key" | "type">): PrimaryKeyInfo {
    const info: PrimaryKeyInfo = {
        fieldName: column.key,
        type: isNumericColumnType(column.type) ? "number" : "string",
        isUUID: column.type.kind === "uuid"
    };
    if (isDateOnlyType(column.type)) info.isDay = true;
    return info;
}

function identityOf(column: ColumnDescriptor): KeyIdentity {
    const kind = column.type.kind;
    if (kind === "uuid") return "uuid";
    if (isSerialType(column.type)) return "serial";
    if (kind === "smallint" || kind === "integer" || kind === "bigint") {
        return column.default?.kind === "identity" ? "identity" : "integer";
    }
    if (kind === "text" || kind === "varchar" || kind === "char") return "text";
    return "other";
}

function isGeneratedKey(column: ColumnDescriptor): boolean {
    if (isSerialType(column.type)) return true;
    const fill = column.default?.kind;
    return fill === "identity" || fill === "random-uuid" || fill === "sql" || fill === "database";
}
